function sk1300_sync_features(): int { if(!sk1300_table('access_features_v1300'))return 0;$n=0;$st=sk1300_db()->prepare('INSERT INTO access_features_v1300(feature_key,label,description,audience,module_group,route_pattern,admin_only,default_guest,default_customer,default_shopkeeper,active,source,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,1,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE label=VALUES(label),description=VALUES(description),audience=VALUES(audience),module_group=VALUES(module_group),route_pattern=IF(access_features_v1300.source="core",VALUES(route_pattern),access_features_v1300.route_pattern),admin_only=VALUES(admin_only),default_guest=VALUES(default_guest),default_customer=VALUES(default_customer),default_shopkeeper=VALUES(default_shopkeeper),active=1,updated_at=NOW()');foreach(sk1300_feature_seed() as $f){[$k,$l,$d,$g,$r,$a,$dg,$dc,$ds]=$f;$st->execute([$k,$l,$d,$g,$g,$r,$a,$dg,$dc,$ds,'core']);$n++;}
 $dir=__DIR__.'/sidebar-modules';if(is_dir($dir))foreach(glob($dir.'/*.json')?:[] as $file){$j=json_decode((string)@file_get_contents($file),true);$rows=(is_array($j)&&isset($j['items'])&&is_array($j['items']))?$j['items']:(is_array($j)?[$j]:[]);foreach($rows as $r){if(!is_array($r))continue;$url=trim((string)($r['url']??''));$key=trim((string)($r['module_key']??''));$label=trim((string)($r['label']??$key));if($url===''||!str_starts_with($url,'/admin/')||$key==='')continue;try{$q=sk1300_db()->prepare('SELECT feature_key FROM access_features_v1300 WHERE admin_only=1 AND route_pattern IN (?,?) LIMIT 1');$q->execute([$url,$url.'*']);if($q->fetchColumn())continue;}catch(Throwable $e){}$fk='admin.module.'.preg_replace('/[^a-z0-9_.-]+/i','_',strtolower($key));try{$st->execute([$fk,$label,(string)($r['description']??'Sidebar module'),'Staff',(string)($r['category_label']??'Administration'),$url.'*',1,0,0,0,'sidebar']);$n++;}catch(Throwable $e){}}
 }
 // Public navigation registry: future public modules automatically enter the checklist, default disabled for restricted audiences.
 foreach(['public_navigation_items_v1051','public_navigation_v1051'] as $t){if(!sk1300_table($t))continue;$c=sk1300_cols($t);$urlCol=isset($c['url'])?'url':(isset($c['href'])?'href':'');$labelCol=isset($c['label'])?'label':(isset($c['title'])?'title':'');if($urlCol===''||$labelCol==='')continue;try{$q=sk1300_db()->query('SELECT `'.$urlCol.'` u,`'.$labelCol.'` l FROM `'.$t.'` LIMIT 500');foreach($q->fetchAll()?:[] as $r){$url=trim((string)$r['u']);if($url===''||str_starts_with($url,'/admin/')||!str_starts_with($url,'/'))continue;$exists=sk1300_db()->prepare('SELECT 1 FROM access_features_v1300 WHERE admin_only=0 AND route_pattern IN (?,?) LIMIT 1');$exists->execute([$url,$url.'*']);if($exists->fetchColumn())continue;$fk='public.nav.'.substr(sha1($url),0,18);$st->execute([$fk,trim((string)$r['l'])?:$url,'Auto-discovered public navigation feature','Public','Public Navigation',$url.'*',0,0,0,0,'public_nav']);$n++;}}catch(Throwable $e){}break;}
 return $n; }

