function sk1300_ensure_tenant(int $tid): void {
 static $done=[]; if(isset($done[$tid]))return; $done[$tid]=true;
 if($tid<0||!sk1300_table('access_tenant_settings_v1300'))return;
 // Performance hotfix v13.0.5.1: normal requests must not re-seed the whole
 // feature/package/role catalog. Seed only for a tenant that has never been initialized.
 try{
   $q=sk1300_db()->prepare('SELECT 1 FROM access_tenant_settings_v1300 WHERE tenant_id=? LIMIT 1');
   $q->execute([$tid]);
   if($q->fetchColumn())return;
 }catch(Throwable $e){}
 sk1300_sync_features();
 try{sk1300_db()->prepare('INSERT INTO access_tenant_settings_v1300(tenant_id,enabled,inherit_global,updated_at) VALUES(?,1,1,NOW()) ON DUPLICATE KEY UPDATE tenant_id=VALUES(tenant_id)')->execute([$tid]);}catch(Throwable $e){}
 if(sk1300_table('access_packages_v1300'))foreach(sk1300_package_templates() as $aud=>$packs)foreach($packs as $p){[$code,$name,$desc,$price,$pub,$def,$features,$limits]=$p;try{$q=sk1300_db()->prepare('SELECT id FROM access_packages_v1300 WHERE tenant_id=? AND audience=? AND package_code=? LIMIT 1');$q->execute([$tid,$aud,$code]);$id=(int)($q->fetchColumn()?:0);if(!$id){sk1300_db()->prepare('INSERT INTO access_packages_v1300(tenant_id,audience,package_code,name,description,price,billing_cycle,duration_days,published,is_default,sort_order,limits_json,created_at,updated_at) VALUES(?,?,?,?,?,? ,"monthly",30,?,?,?, ?,NOW(),NOW())')->execute([$tid,$aud,$code,$name,$desc,$price,$pub,$def,$def?10:50,json_encode($limits,JSON_UNESCAPED_SLASHES)]);$id=(int)sk1300_db()->lastInsertId();}if($id&&sk1300_table('access_package_features_v1300'))foreach($features as $fk){sk1300_db()->prepare('INSERT INTO access_package_features_v1300(tenant_id,package_id,feature_key,enabled,updated_at) VALUES(?,?,?,1,NOW()) ON DUPLICATE KEY UPDATE package_id=VALUES(package_id)')->execute([$tid,$id,$fk]);}}catch(Throwable $e){}}
 if(sk1300_table('access_roles_v1300'))foreach(sk1300_role_templates() as $rk=>$r){try{sk1300_db()->prepare('INSERT INTO access_roles_v1300(tenant_id,role_key,name,description,is_system,active,sort_order,created_at,updated_at) VALUES(?,?,?,?,1,1,100,NOW(),NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name),description=VALUES(description),active=1')->execute([$tid,$rk,$r[0],$r[1]]);foreach(sk1300_role_default_features($rk) as $fk)sk1300_db()->prepare('INSERT INTO access_role_features_v1300(tenant_id,role_key,feature_key,enabled,updated_at) VALUES(?,?,?,1,NOW()) ON DUPLICATE KEY UPDATE role_key=VALUES(role_key)')->execute([$tid,$rk,$fk]);}catch(Throwable $e){}}
}
function sk1300_settings(int $tid): array {
 static $cache=[]; if(isset($cache[$tid]))return $cache[$tid];
 $d=['enabled'=>1,'inherit_global'=>1,'default_customer_package_code'=>'customer_free','default_shopkeeper_package_code'=>'shopkeeper_starter','new_guest_features'=>0,'new_customer_features'=>0,'new_shopkeeper_features'=>0,'new_staff_features'=>0];
 if(!sk1300_table('access_tenant_settings_v1300'))return $cache[$tid]=$d;
 try{$q=sk1300_db()->prepare('SELECT * FROM access_tenant_settings_v1300 WHERE tenant_id=? LIMIT 1');$q->execute([$tid]);return $cache[$tid]=array_merge($d,$q->fetch()?:[]);}catch(Throwable $e){return $cache[$tid]=$d;}
}
function sk1300_feature_for_tenant(string $key,int $tid=0): array {
 $tid=$tid?:sk1300_tid(); static $cache=[]; $ck=$tid."\0".$key; if(array_key_exists($ck,$cache))return $cache[$ck];
 if(sk1300_table('access_tenant_custom_features_v1301'))try{$q=sk1300_db()->prepare('SELECT id,feature_key,label,description,audience,module_group,route_pattern,admin_only,default_guest,default_customer,default_shopkeeper,active,"tenant_custom" source FROM access_tenant_custom_features_v1301 WHERE tenant_id=? AND feature_key=? AND active=1 LIMIT 1');$q->execute([$tid,$key]);$r=$q->fetch()?:[];if($r)return $cache[$ck]=$r;}catch(Throwable $e){}
 if(!sk1300_table('access_features_v1300'))return $cache[$ck]=[];
 try{$q=sk1300_db()->prepare('SELECT * FROM access_features_v1300 WHERE feature_key=? AND active=1 LIMIT 1');$q->execute([$key]);return $cache[$ck]=$q->fetch()?:[];}catch(Throwable $e){return $cache[$ck]=[];}
}
function sk1300_feature(string $key): array {return sk1300_feature_for_tenant($key,sk1300_tid());}
function sk1300_path_feature(string $path,bool $admin): array {
 $path=parse_url($path,PHP_URL_PATH)?:$path; $tid=sk1300_tid();
 static $indexes=[]; $ik=$tid.':'.($admin?1:0);
 if(!isset($indexes[$ik])){
   $rows=[];
   if(sk1300_table('access_tenant_custom_features_v1301'))try{$q=sk1300_db()->prepare('SELECT id,feature_key,label,description,audience,module_group,route_pattern,admin_only,default_guest,default_customer,default_shopkeeper,active,"tenant_custom" source FROM access_tenant_custom_features_v1301 WHERE tenant_id=? AND active=1 AND admin_only=? AND route_pattern IS NOT NULL AND route_pattern<>""');$q->execute([$tid,$admin?1:0]);$rows=array_merge($rows,$q->fetchAll()?:[]);}catch(Throwable $e){}
   if(sk1300_table('access_features_v1300'))try{$q=sk1300_db()->prepare('SELECT * FROM access_features_v1300 WHERE active=1 AND admin_only=? AND route_pattern IS NOT NULL AND route_pattern<>""');$q->execute([$admin?1:0]);$rows=array_merge($rows,$q->fetchAll()?:[]);}catch(Throwable $e){}
   usort($rows,static fn($a,$b)=>strlen((string)($b['route_pattern']??''))<=>strlen((string)($a['route_pattern']??'')));
